metadata.value:
@{
            var jwt = (Jwt)context.Variables["jwt"];
            var roles  = jwt.Claims.ContainsKey("roles")  ? jwt.Claims["roles"].Length  : 0;
            var groups = jwt.Claims.ContainsKey("groups") ? jwt.Claims["groups"].Length : 0;
            var scopes = jwt.Claims.ContainsKey("scp") ? string.Join(" ", jwt.Claims["scp"]).Split(' ').Length : 0;
            var overage = jwt.Claims.ContainsKey("_claim_names") ? "yes" : "no";
            return "roles=" + roles + " groups=" + groups + " scopes=" + scopes + " groupsOverage=" + overage;
        }

@{
            if ("{{mcp-hub-graph-fallback}}" != "true") { return "off"; }
            if (JArray.Parse((string)context.Variables["pendingGroups"]).Count == 0) { return "not-needed"; }
            if (!context.Variables.ContainsKey("graphGroups")) {
                if (!context.Variables.ContainsKey("graphToken")) { return "failed(token-acquisition)"; }
                if (context.Variables.ContainsKey("graphResp") && context.Variables["graphResp"] != null) { return "failed(http-" + ((IResponse)context.Variables["graphResp"]).StatusCode + ")"; }
                return "failed(no-response)";
            }
            return "verified=" + JArray.Parse((string)context.Variables["graphGroups"]).Count + "/" + JArray.Parse((string)context.Variables["pendingGroups"]).Count;
        }
